package dev.sablelife.testing;
import dev.sablelife.SableLife;
import dev.sablelife.heart.*;
import dev.sablelife.module.*;
import dev.sablelife.compat.sable.SableBodyProbe;
import dev.ryanhcode.sable.api.SubLevelAssemblyHelper;
import dev.ryanhcode.sable.companion.math.BoundingBox3i;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.phys.Vec3;
import net.neoforged.neoforge.gametest.*;
import java.util.*;
@GameTestHolder("sablelife_control_tests") @PrefixGameTestTemplate(false)
public final class LaserBreakingGameTests {
    private static HeartBlockEntity fixture(GameTestHelper h){var l=h.getLevel();var p=h.absolutePos(new BlockPos(3,6,3));l.setBlockAndUpdate(p,SableLife.HEART.get().defaultBlockState());l.setBlockAndUpdate(p.east(),Blocks.IRON_BLOCK.defaultBlockState());var b=SubLevelAssemblyHelper.assembleBlocks(l,p,List.of(p,p.east()),new BoundingBox3i(p.getX(),p.getY(),p.getZ(),p.getX()+1,p.getY(),p.getZ()));var c=(HeartBlockEntity)l.getBlockEntity(b.getPlot().getCenterBlock());c.tryActivate(TestActors.creative(l));return c;}
    private static Vec3 origin(HeartBlockEntity c){return SableBodyProbe.toWorld(c.getLevel(),c.getBlockPos().getCenter());}
    @GameTest(template="combat",batch="laser_protected_body") public static void ProtectedOtherLifeformStopsCut(GameTestHelper h){
        var source=fixture(h);var p=BlockPos.containing(origin(source)).east(5);var level=h.getLevel();level.setBlockAndUpdate(p,SableLife.HEART.get().defaultBlockState());level.setBlockAndUpdate(p.east(),Blocks.IRON_BLOCK.defaultBlockState());var body=SubLevelAssemblyHelper.assembleBlocks(level,p,List.of(p,p.east()),new BoundingBox3i(p.getX(),p.getY(),p.getZ(),p.getX()+1,p.getY(),p.getZ()));var target=(HeartBlockEntity)level.getBlockEntity(body.getPlot().getCenterBlock());target.tryActivate(TestActors.creative(level));level.setBlockAndUpdate(p.east(4),Blocks.STONE.defaultBlockState());h.runAfterDelay(2,()->{var targetWorld=origin(target);var result=LaserBlockCut.cut(level,source,new VirtualModule("laser"),origin(source),origin(source).add(12,0,0),new LaserBlockCut.Front(),level.getGameTime());h.assertTrue(level.getBlockEntity(target.getBlockPos())==target&&level.getBlockState(p.east(4)).is(Blocks.STONE),"Cut removed protected lifeform or penetrated it: target="+target.health().state()+", locked="+dev.sablelife.ownership.BodyProtection.locked(level,target.getBlockPos())+", origin="+origin(source)+", targetPos="+targetWorld+", end="+result+", corePresent="+(level.getBlockEntity(target.getBlockPos())==target));h.succeed();});
    }
    @GameTest(template="combat",batch="laser_unloaded_end") public static void CuttingDoesNotLoadRemoteTerrain(GameTestHelper h){var c=fixture(h);var end=origin(c).add(1024,0,0);var far=BlockPos.containing(end);h.assertTrue(!h.getLevel().hasChunkAt(far),"Test endpoint already loaded");var result=LaserBlockCut.cut(h.getLevel(),c,new VirtualModule("laser"),origin(c),end,new LaserBlockCut.Front(),h.getLevel().getGameTime());h.assertTrue(!h.getLevel().hasChunkAt(far)&&result.distanceTo(end)>1,"Cut force-loaded remote terrain");h.succeed();}
    @GameTest(template="combat",batch="laser_instant") public static void WholeLineRemovesWallsButSkipsOwnBodyAndStopsAtBedrock(GameTestHelper h){var c=fixture(h);var p=BlockPos.containing(origin(c));for(int i=3;i<=6;i++)h.getLevel().setBlockAndUpdate(p.east(i),Blocks.STONE.defaultBlockState());h.getLevel().setBlockAndUpdate(p.east(5),Blocks.BEDROCK.defaultBlockState());var m=new VirtualModule("laser");var end=LaserBlockCut.cut(h.getLevel(),c,m,origin(c),origin(c).add(12,0,0),new LaserBlockCut.Front(),h.getLevel().getGameTime());h.assertTrue(h.getLevel().getBlockState(p.east(3)).isAir()&&h.getLevel().getBlockState(p.east(4)).isAir(),"Instant line did not clear walls");h.assertTrue(h.getLevel().getBlockState(p.east(5)).is(Blocks.BEDROCK)&&h.getLevel().getBlockState(p.east(6)).is(Blocks.STONE)&&end.distanceTo(origin(c))<5,"Cut passed unbreakable wall");h.assertTrue(h.getLevel().getBlockState(c.getBlockPos().east()).is(Blocks.IRON_BLOCK),"Own body was destroyed");h.succeed();}
    @GameTest(template="combat",batch="laser_progressive") public static void ProgressiveCutStartsAtFirstWallAndUsesBlocksPerSecond(GameTestHelper h){var c=fixture(h);var p=BlockPos.containing(origin(c));for(int i=3;i<=5;i++)h.getLevel().setBlockAndUpdate(p.east(i),Blocks.STONE.defaultBlockState());var m=new VirtualModule("laser");m.edit("laserBreakMode",1,"");m.edit("laserBreakSpeed",2,"");var front=new LaserBlockCut.Front();long now=h.getLevel().getGameTime();LaserBlockCut.cut(h.getLevel(),c,m,origin(c),origin(c).add(12,0,0),front,now);h.assertTrue(h.getLevel().getBlockState(p.east(3)).isAir()&&!h.getLevel().getBlockState(p.east(4)).isAir(),"Initial cut removed more than first wall");LaserBlockCut.cut(h.getLevel(),c,m,origin(c),origin(c).add(12,0,0),front,now+10);h.assertTrue(h.getLevel().getBlockState(p.east(4)).isAir()&&!h.getLevel().getBlockState(p.east(5)).isAir(),"2 blocks/s did not advance one block in half-second");LaserBlockCut.cut(h.getLevel(),c,m,origin(c),origin(c).add(12,0,0),front,now+20);h.assertTrue(h.getLevel().getBlockState(p.east(5)).isAir(),"Progressive cut did not continue");h.succeed();}
    @GameTest(template="combat",batch="laser_charge_break",timeoutTicks=40) public static void ChargingNeverBreaksAndEnabledFiringDoes(GameTestHelper h){var c=fixture(h);var p=BlockPos.containing(origin(c)).east(4);h.getLevel().setBlockAndUpdate(p,Blocks.STONE.defaultBlockState());var m=c.modules().add("laser");m.anchors(List.of(ModuleAnchor.create(c,c.getBlockPos(),Direction.EAST)));m.edit("chargeTime",2,"");m.edit("beamHits",10,"");m.edit("laserBreakBlocks",1,"");c.modules().tick(c);h.runAfterDelay(1,()->{c.modules().tick(c);h.assertTrue(h.getLevel().getBlockState(p).is(Blocks.STONE),"Charging broke terrain");});h.runAfterDelay(3,()->{var current=BlockPos.containing(m.anchors().getFirst().world(c,false).add(ModuleCombat.direction(c,m).scale(4)));h.getLevel().setBlockAndUpdate(current,Blocks.STONE.defaultBlockState());c.modules().tick(c);h.assertTrue(h.getLevel().getBlockState(current).isAir(),"Firing did not break terrain; state="+c.health().state()+", trigger="+HeartModules.triggered(m,c)+", phase="+c.modules().snapshot(c,false).getList("Modules",10).getCompound(0).getString("LaserPhase"));m.edit("enabled",0,"");h.succeed();});}
    @GameTest(template="combat",batch="laser_break_off",timeoutTicks=30) public static void DefaultOffRetainsWallAndSettingsPersist(GameTestHelper h){var c=fixture(h);var p=BlockPos.containing(origin(c)).east(4);h.getLevel().setBlockAndUpdate(p,Blocks.STONE.defaultBlockState());var m=c.modules().add("laser");m.anchors(List.of(ModuleAnchor.create(c,c.getBlockPos(),Direction.EAST)));m.edit("chargeTime",0,"");m.edit("beamHits",10,"");c.modules().tick(c);h.runAfterDelay(3,()->{c.modules().tick(c);h.assertTrue(h.getLevel().getBlockState(p).is(Blocks.STONE)&&m.value("laserBreakBlocks")==0,"Default beam destroyed wall");m.edit("laserBreakBlocks",1,"");m.edit("laserBreakMode",1,"");m.edit("laserBreakSpeed",3.5,"");var copy=VirtualModule.load(m.save());h.assertTrue(copy.value("laserBreakBlocks")==1&&copy.value("laserBreakMode")==1&&copy.value("laserBreakSpeed")==3.5,"Cut settings lost on save");m.edit("enabled",0,"");h.succeed();});}
}
